import socket,time,sys,json
import arena

def analyze(b,secs=60,searchmoves=None):
 s=socket.socket(socket.AF_UNIX);s.connect('/run/match/opponent-stockfish.sock');f=s.makefile('r')
 def send(x):s.sendall((x+'\n').encode())
 send('uci')
 for l in f:
  if l.strip()=='uciok':break
 send('setoption name Threads value 2');send('setoption name Hash value 256');send('isready')
 for l in f:
  if l.strip()=='readyok':break
 send('position startpos moves '+' '.join(m.uci() for m in b.move_stack))
 send('go movetime '+str(int(secs*1000))+(' searchmoves '+' '.join(searchmoves) if searchmoves else ''))
 last=''
 for l in f:
  l=l.strip()
  if l.startswith('info'):
   last=l
   if ' depth ' in l: print(l,flush=True)
  if l.startswith('bestmove'):
   move=l.split()[1];break
 send('quit');s.close()
 return move,last
if __name__=='__main__':
 b=arena.load_board();move,info=analyze(b,float(sys.argv[1]) if len(sys.argv)>1 else 60)
 print('CHOSEN',move,flush=True)
 if '--play' in sys.argv:arena.cmd_move(move)
